package app.dayflow.assistant;import android.content.*;import android.os.*;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;
public final class MainActivity extends AppCompatActivity {public void onCreate(Bundle state){super.onCreate(state);LinearLayout page=new LinearLayout(this);page.setOrientation(1);page.setPadding(32,80,32,40);setContentView(page);TextView help=new TextView(this);help.setTextSize(18);help.setText("本机助手API\n仅监听127.0.0.1:8766，使用Bearer密钥。\n需蓝心小V/小爱同学支持自定义HTTP工具或由自动化工具桥接；不承诺厂商直接集成。\n停止后不占用监听端口。");page.addView(help);Button start=new Button(this);start.setText("开启本机接口");page.addView(start);start.setOnClickListener(v->{if(!"app.dayflow".equals(getCallingPackage())||getIntent().getIntExtra("dayflow_protocol",0)!=1){help.setText("请从日栖设置→开放API启动");return;}String token=getIntent().getStringExtra("dayflow_api_token");if(token==null||token.isEmpty())return;if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},1);startForegroundService(new Intent(this,ApiService.class).putExtra("token",token));help.setText("已请求开启；状态与停止入口见常驻通知。地址http://127.0.0.1:8766，需Authorization: Bearer <密钥>。");});Button stop=new Button(this);stop.setText("停止接口");stop.setOnClickListener(v->{stopService(new Intent(this,ApiService.class));help.setText("接口已停止");});page.addView(stop);}}
